import{_ as n,c as o,o as s,a3 as a}from"./chunks/framework.CoV49S2T.js";const h=JSON.parse('{"title":"Choix de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy-choices.md","filePath":"fr/guide/privacy-choices.md","lastUpdated":1786595765000}'),i={name:"fr/guide/privacy-choices.md"};function t(r,e,l,d,u,c){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="choix-de-confidentialite" tabindex="-1">Choix de confidentialité <a class="header-anchor" href="#choix-de-confidentialite" aria-label="Permalink to &quot;Choix de confidentialité&quot;">​</a></h1><p>ClipboardxAI est une application locale d&#39;abord. Comme vos données restent sur votre appareil, nous ne collectons, ne vendons ni ne partageons aucune information personnelle.</p><h2 id="donnees-que-nous-detenons-localement" tabindex="-1">Données que nous détenons localement <a class="header-anchor" href="#donnees-que-nous-detenons-localement" aria-label="Permalink to &quot;Données que nous détenons localement&quot;">​</a></h2><p>ClipboardxAI stocke toutes les données localement sur votre Mac :</p><ul><li>Historique du presse-papiers et préférences de l&#39;application</li><li>Actions et configuration personnalisées</li><li>Clés API (dans le Keychain, uniquement si vous configurez un fournisseur cloud)</li><li>Journaux de débogage (si activés)</li></ul><p>Aucune de ces données n&#39;est téléversée vers un serveur par l&#39;application elle-même.</p><h2 id="option-d-ia-cloud" tabindex="-1">Option d&#39;IA cloud <a class="header-anchor" href="#option-d-ia-cloud" aria-label="Permalink to &quot;Option d&#39;IA cloud&quot;">​</a></h2><p>Les fonctionnalités d&#39;IA cloud sont <strong>désactivées par défaut</strong>. Elles n&#39;envoient du contenu qu&#39;au fournisseur que vous choisissez, en utilisant votre propre clé API, et uniquement lorsque vous déclenchez une action cloud. Vous pouvez consulter ou supprimer les fournisseurs configurés dans <strong>Réglages → IA</strong>.</p><h2 id="vos-droits" tabindex="-1">Vos droits <a class="header-anchor" href="#vos-droits" aria-label="Permalink to &quot;Vos droits&quot;">​</a></h2><p>Étant donné que ClipboardxAI ne collecte ni ne stocke de données personnelles sur nos serveurs, il n&#39;y a aucune donnée personnelle pour nous à consulter, supprimer ou transférer. Toutes vos données peuvent être gérées directement dans l&#39;application ou en supprimant le dossier conteneur de l&#39;application :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span></code></pre></div><h2 id="ne-pas-vendre" tabindex="-1">Ne pas vendre <a class="header-anchor" href="#ne-pas-vendre" aria-label="Permalink to &quot;Ne pas vendre&quot;">​</a></h2><p>ClipboardxAI ne vend aucune information personnelle. Nous n&#39;utilisons aucune analytique, publicité ou service de suivi tiers d&#39;aucune sorte.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Si vous avez des questions sur les choix de confidentialité, ouvrez un ticket à l&#39;adresse : <code>https://github.com/clipboardxAI/clipboard-site/issues</code></p>',15)])])}const v=n(i,[["render",t]]);export{h as __pageData,v as default};
